with a as(select * from public.authors where open_library_id=any(array['OL21594A','OL33146A','OL9388A','OL32293A','OL153884A']::text[])),w as(select * from public.works where open_library_id=any(array['OL498463W','OL66513W','OL362699W','OL100672W','OL258758W','OL1456910W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9783956763717','9781730712241','9781616511104','9781580491624','9780582427136','9789029554343','9789021469911','9789027491428','9789035108363','9789035108318','9789020425895']::text[]) or open_library_edition_id=any(array['OL50698005M','OL40826271M','OL27668659M','OL12276611M','OL28426674M','OL3487091M','OL24328781M','OL24632641M','OL24354728M','OL24405542M','OL24405545M','OL24651397M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987111001 and 987111999),'editions',(select count(*) from public.editions where id between 987211001 and 987211999),'authors',(select count(*) from public.authors where id between 987311001 and 987311999))) as preflight;
